using System; using System.Collections; using System.Globalization; using System.Linq; using Forge.Interface; using Forge.Pont; using UnityEngine; using UnityEngine.UI;
namespace ForgeLocal3D.Captures {
    // Lot 964 : la photo du lot 658 (Mistra, 60 %, trente jours, le feuillet ouvert), en mode Flux, l'infobulle de la légende ouverte : plus aucune légende flottante. `-forge964Fleches` rallume les flèches en mode Puissances, dans l'image du contrôle : la capture doit échouer sur « flèche visible hors du mode Flux ».
    static class Lot964 {
        const string FLECHES = "-forge964Fleches", FEUILLET = "Terres et comptes"; static readonly string[] FLOTTANTES = { "Légende des lieux", "Légende des flèches", "Fond de la légende", "Fond des flèches" }; static InvalidOperationException Echec(string cause) => new InvalidOperationException(cause); static string Ligne(string t) => (t ?? "(aucun)").Replace("\r", "").Replace("\n", " | ");
        static Rect Ecran(Camera camera, RectTransform cadre) { var coins = new Vector3[4]; cadre.GetWorldCorners(coins); var p = coins.Select(c => camera.WorldToScreenPoint(c)).ToArray(); return Rect.MinMaxRect(p.Min(v => v.x), p.Min(v => v.y), p.Max(v => v.x), p.Max(v => v.y)); }
        [ScenarioDeCapture(964, "flux-et-infobulle")] static IEnumerator FluxEtInfobulle(Camera camera) {
            for (var e = Lot658.FlechesDuSiege(camera); e.MoveNext();) yield return null; CarteDessinee carte = Lot658.carte; Transform toile = Lot658.toile; // étape 1
            CalquesCarte calques = carte.GetComponent<CalquesCarte>() ?? throw Echec("étape 1 : pas de CalquesCarte"); LieuxDeCarte lieux = carte.GetComponent<LieuxDeCarte>() ?? throw Echec("étape 1 : pas de LieuxDeCarte"); FlechesDeCarte fleches = carte.GetComponent<FlechesDeCarte>() ?? throw Echec("étape 1 : pas de FlechesDeCarte");
            (carte.GetComponent<SurvolDeCarte>() ?? throw Echec("étape 1 : pas de survol")).automatique = true; (carte.GetComponent<ParcoursDeCarte>() ?? throw Echec("étape 1 : pas de parcours")).automatique = true; (carte.GetComponent<InfobulleDeTerre>() ?? throw Echec("étape 1 : pas d'InfobulleDeTerre")).automatique = true;
            string flottante = toile.GetComponentsInChildren<Transform>(true).Select(t => t.name).FirstOrDefault(FLOTTANTES.Contains); if (flottante != null) throw Echec("légende flottante encore là : " + flottante); // étape 2
            var fond = (RectTransform)toile.Find(CalquesCarte.LEGENDE); var bande = (RectTransform)toile.Find(CalquesCarte.BANDE); var bulle = fond.GetComponent<Infobulle>(); Transform racine = carte.transform.Find(FlechesDeCarte.RACINE) ?? throw Echec("étape 1 : aucune « " + FlechesDeCarte.RACINE + " »");
            int Visibles() => racine.Cast<Transform>().Count(f => f.gameObject.activeInHierarchy); void Cliquer(string mode) => (bande.Find(mode)?.GetComponent<Button>() ?? throw Echec("bouton « " + mode + " » introuvable")).onClick.Invoke();
            Cliquer("Puissances"); string puissances = CalquesCarte.LegendeDuMode(ModeDeCarte.Puissances, null, true); // étape 3
            for (var e = Lot690.Jusqua(() => calques.Legende.text == puissances && bulle.Phrase == puissances + "\n" + CalquesCarte.DetailDuMode(ModeDeCarte.Puissances, lieux, fleches), () => "étape 3 : légende « " + Ligne(calques.Legende.text) + " », infobulle « " + Ligne(bulle.Phrase) + " »"); e.MoveNext();) yield return null;
            if (Environment.GetCommandLineArgs().Contains(FLECHES)) racine.gameObject.SetActive(true); var vue = racine.Cast<Transform>().FirstOrDefault(f => f.gameObject.activeInHierarchy); if (vue != null) throw Echec("flèche visible hors du mode Flux : " + vue.name); // dans l'image du contrôle, sans yield
            var disques = carte.transform.Find(LieuxDeCarte.RACINE); if (disques == null || !disques.Cast<Transform>().Any(l => l.Find("Disque") is Transform d && d.gameObject.activeInHierarchy)) throw Echec("étape 3 : aucun disque de lieu actif en Puissances");
            Cliquer("Flux"); for (var e = Lot690.Jusqua(() => calques.Legende.text == CalquesCarte.FLUX && bulle.Phrase == CalquesCarte.FLUX + "\n" + CalquesCarte.DetailDuMode(ModeDeCarte.Flux, lieux, fleches) && Visibles() > 0, () => "étape 4 : légende « " + Ligne(calques.Legende.text) + " », infobulle « " + Ligne(bulle.Phrase) + " », flèches visibles " + Visibles()); e.MoveNext();) yield return null;
            string texte = bulle.Phrase; RectTransform feuillet = Infobulle.Montrer(toile.GetComponent<Canvas>(), texte, Ecran(camera, fond).center); // étape 5, puis les flèches des lieux recadrées entre les dossiers, au-dessus de l'infobulle, comme Lot658.Cadrer
            float x0 = 764f / 1920f + .01f, x1 = .66f, y0 = Ecran(camera, feuillet).yMax / camera.pixelHeight + .02f, y1 = .88f; var b = racine.Cast<Transform>().Where(f => f.name != FlechesDeCarte.DU).Select(f => f.GetComponent<MeshFilter>().sharedMesh.bounds).ToArray(); float minX = b.Min(o => o.min.x), maxX = b.Max(o => o.max.x), minZ = b.Min(o => o.min.z), maxZ = b.Max(o => o.max.z);
            float demi = Mathf.Max(VueDeCarte.DEMI_MIN_KM, (maxX - minX) / (2f * Lot549.FORME * (x1 - x0) * .8f), (maxZ - minZ) / (2f * (y1 - y0) * .8f)); carte.Vue.Centrer(new Vector2((minX + maxX) / 2f - ((x0 + x1) / 2f - .5f) * 2f * demi * Lot549.FORME, (minZ + maxZ) / 2f - ((y0 + y1) / 2f - .5f) * 2f * demi), demi); carte.Vue.Poser(camera, carte.transform, CarteDessinee.HAUTEUR_CAMERA); for (int i = 0; i < 10; i++) yield return null;
            var image = new Rect(0, 0, camera.pixelWidth, camera.pixelHeight); bool Dans(Rect r) => r.xMin >= -.5f && r.yMin >= -.5f && r.xMax <= image.xMax + .5f && r.yMax <= image.yMax + .5f; Text ecrit = feuillet.GetComponentInChildren<Text>(true); Rect cadre = Ecran(camera, feuillet);
            if (!feuillet.gameObject.activeInHierarchy || ecrit == null || ecrit.text != texte || !Dans(cadre)) throw Echec("étape 5 : infobulle « " + Ligne(ecrit?.text) + " » " + (feuillet.gameObject.activeInHierarchy ? "en " + cadre + " dans " + image : "cachée"));
            foreach (var zone in new[] { fond, bande }) { Rect r = Ecran(camera, zone); if (!Dans(r)) throw Echec("étape 5 : « " + zone.name + " » hors de l'image : " + r + " dans " + image);
                foreach (string panneau in new[] { FEUILLET, "Votre maison", "Territoire conservé", "FORGE · Le cabinet", "Parcourir le monde" }) { var p = toile.Cast<Transform>().OfType<RectTransform>().FirstOrDefault(t => t.name == panneau && (panneau != FEUILLET || t.GetComponentInChildren<ScrollRect>(true) != null)) ?? throw Echec("étape 5 : « " + panneau + " » introuvable");
                    if (!p.gameObject.activeInHierarchy) throw Echec("étape 5 : « " + panneau + " » caché"); if (r.Overlaps(Ecran(camera, p))) throw Echec("étape 5 : « " + zone.name + " » recouvre « " + panneau + " »"); } }
            Debug.Log("CAPTURE_964 mode Flux · légende « " + Ligne(calques.Legende.text) + " » · infobulle " + texte.Split('\n').Length + " lignes · flèches " + Visibles() + " visibles · tick " + carte.GetComponent<CabinetDeCarte>().Partie.Monde.Donnees.Monde.Tick.ToString(CultureInfo.InvariantCulture)); // étape 6
        } } }
